@@ -0,0 +1,111 @@
+import { cookies } from 'next/headers';
+import Link from 'next/link';
+import { redirect } from 'next/navigation';
+import { getSession } from '@/lib/session';
+import { getStore } from '@/lib/session-store';
+import { getRoiSummary } from '@/lib/analytics/roi-metrics';
+import { Card, Badge } from '@/design-system/primitives';
+import { ChevronLeft } from 'lucide-react';
+
+const PLATFORM_COST_USD = Number(process.env.PLATFORM_COST_USD_PER_VOYAGE ?? '500');
+
+function formatUsd(value: number): string {
+  return new Intl.NumberFormat('en-US', { style: 'currency', currency: 'USD', maximumFractionDigits: 0 }).format(value);
+}
+
+export default async function RoiReportPage() {
+  const cookieStore = await cookies();
+  const sessionId = cookieStore.get('session_id')?.value;
+  if (!sessionId) redirect('/');
+
+  const session = getSession(sessionId);
+  if (!session) redirect('/');
+
+  const db = getStore().getDatabase();
+  const summary = getRoiSummary(db, PLATFORM_COST_USD, 90);
+
+  const isEmpty = summary.totalVoyages === 0;
+
+  return (
+    <main className="min-h-screen bg-ds-bg py-4 sm:py-8 px-3 sm:px-4">
+      <div className="max-w-3xl mx-auto space-y-4 sm:space-y-6">
+        <Link
+          href="/dashboard"
+          className="flex items-center gap-1 text-sm text-ds-text-muted hover:text-ds-text transition-colors duration-ds-fast"
+        >
+          <ChevronLeft className="h-4 w-4" /> Back to Dashboard
+        </Link>
+
+        <div>
+          <Badge variant="info">ANALYTICS</Badge>
+          <h1 className="text-lg sm:text-xl font-bold mt-2 text-ds-text">ROI Report — Last 90 Days</h1>
+          <p className="text-sm text-ds-text-muted">
+            Platform cost assumption: {formatUsd(PLATFORM_COST_USD)} per voyage
+          </p>
+        </div>
+
+        {isEmpty ? (
+          <Card padding="md">
+            <p className="text-sm text-ds-text-muted text-center py-6">
+              No data yet — voyage metrics will appear here once deals close.
+            </p>
+          </Card>
+        ) : (
+          <>
+            {/* Summary KPIs */}
+            <Card padding="md">
+              <h2 className="text-sm font-semibold text-ds-text-muted uppercase tracking-wide mb-3">Summary</h2>
+              <div className="grid grid-cols-2 sm:grid-cols-4 gap-4">
+                <div className="text-center">
+                  <p className="text-2xl font-bold text-ds-text">{summary.totalVoyages}</p>
+                  <p className="text-xs text-ds-text-muted mt-1">Total Voyages</p>
+                </div>
+                <div className="text-center">
+                  <p className="text-2xl font-bold text-ds-text">{formatUsd(summary.totalSavingsUsd)}</p>
+                  <p className="text-xs text-ds-text-muted mt-1">Total Savings</p>
+                </div>
+                <div className="text-center">
+                  <p className="text-2xl font-bold text-ds-text">{formatUsd(summary.avgSavingsPerVoyage)}</p>
+                  <p className="text-xs text-ds-text-muted mt-1">Avg Savings / Voyage</p>
+                </div>
+                <div className="text-center">
+                  <p className="text-2xl font-bold text-ds-text">{summary.roiMultiple.toFixed(1)}x</p>
+                  <p className="text-xs text-ds-text-muted mt-1">ROI Multiple</p>
+                </div>
+              </div>
+            </Card>
+
+            {/* Cohort table */}
+            {summary.cohorts.length > 0 && (
+              <Card padding="md">
+                <h2 className="text-sm font-semibold text-ds-text-muted uppercase tracking-wide mb-3">Monthly Cohorts</h2>
+                <div className="overflow-x-auto">
+                  <table className="w-full text-sm">
+                    <thead>
+                      <tr className="border-b border-ds-border">
+                        <th className="text-left py-2 text-ds-text-muted font-medium">Month</th>
+                        <th className="text-right py-2 text-ds-text-muted font-medium">Voyages</th>
+                        <th className="text-right py-2 text-ds-text-muted font-medium">Total Savings</th>
+                        <th className="text-right py-2 text-ds-text-muted font-medium">Avg Savings</th>
+                      </tr>
+                    </thead>
+                    <tbody>
+                      {summary.cohorts.map((cohort) => (
+                        <tr key={cohort.month} className="border-b border-ds-border last:border-0">
+                          <td className="py-2 text-ds-text font-medium">{cohort.month}</td>
+                          <td className="py-2 text-ds-text text-right">{cohort.voyages}</td>
+                          <td className="py-2 text-ds-text text-right">{formatUsd(cohort.totalSavings)}</td>
+                          <td className="py-2 text-ds-text text-right">{formatUsd(cohort.avgSavings)}</td>
+                        </tr>
+                      ))}
+                    </tbody>
+                  </table>
+                </div>
+              </Card>
+            )}
+          </>
+        )}
+      </div>
+    </main>
+  );
+}
