+
+const MOU_LABEL: Record<string, { label: string; cls: string }> = {
+  white: { label: 'White List', cls: 'text-emerald-700 bg-emerald-50 border-emerald-200' },
+  grey:  { label: 'Grey List',  cls: 'text-amber-700  bg-amber-50  border-amber-200'  },
+  black: { label: 'Black List', cls: 'text-red-700    bg-red-50    border-red-200'    },
+};
+
+const RISK_CLS: Record<string, string> = {
+  none:   'text-emerald-700',
+  low:    'text-amber-600',
+  medium: 'text-orange-600',
+  high:   'text-red-700',
+};
+
+function Row({ label, value }: { label: string; value: ReactNode }) {
+  return (
+    <div className="flex justify-between text-sm py-1 border-b border-ds-border last:border-0">
+      <span className="text-ds-text-muted">{label}</span>
+      <span className="font-medium text-ds-text text-right">{value}</span>
+    </div>
+  );
+}
+
+export function VesselPassportPanel({ passport }: { passport: VesselPassport }) {
+  const mou = passport.flag.parisMou ? MOU_LABEL[passport.flag.parisMou] : null;
+
+  return (
+    <div className="rounded-ds-md border border-ds-border bg-ds-surface p-4 space-y-3">
+      <h4 className="text-xs font-semibold text-ds-text-muted uppercase tracking-wide">
+        Vessel Passport
+      </h4>
+
+      <div>
+        <Row
+          label="Flag"
+          value={
+            <span className="flex items-center gap-2 justify-end">
+              {passport.flag.country || '—'}
+              {mou && (
+                <span className={`text-xs px-1.5 py-0.5 rounded border font-medium ${mou.cls}`}>
+                  {mou.label}
+                </span>
+              )}
+            </span>
+          }
+        />
+        <Row
+          label="Class society"
+          value={
+            <span>
+              {passport.class.society || '—'}
+              {passport.class.society && (
+                <span className={`ml-1 text-xs ${passport.class.isIacs ? 'text-emerald-600' : 'text-ds-text-muted'}`}>
+                  {passport.class.isIacs ? '✓ IACS' : '(non-IACS)'}
+                </span>
+              )}
+            </span>
+          }
+        />
+        <Row
+          label="P&amp;I club"
+          value={
+            <span>
+              {passport.pi.club || '—'}
+              {passport.pi.club && (
+                <span className={`ml-1 text-xs ${passport.pi.isIg ? 'text-emerald-600' : 'text-ds-text-muted'}`}>
+                  {passport.pi.isIg ? '✓ IG' : '(non-IG)'}
+                </span>
+              )}
+            </span>
+          }
+        />
+        {passport.age != null && <Row label="Age" value={`${passport.age} yr`} />}
+        {passport.psc != null && (
+          <Row
+            label="PSC detentions (3y)"
+            value={
+              <span className={passport.psc.detentions3y > 0 ? 'text-amber-600' : 'text-emerald-600'}>
+                {passport.psc.detentions3y}
+              </span>
+            }
+          />
+        )}
+        <Row
+          label="Shadow-fleet risk"
+          value={
+            <span className={RISK_CLS[passport.shadowFleet.riskLevel] ?? ''}>
+              {passport.shadowFleet.riskLevel.toUpperCase()}
+            </span>
