--- /dev/null
+++ b/scripts/backfill-lastcargoes.ts
@@ -0,0 +1,79 @@
+/**
+ * Idempotent backfill: apply regex lastCargoes extraction to all cached vessel
+ * parse results where the LLM produced a null lastCargoes field.
+ *
+ * Safe to re-run: only writes rows where at least one vessel is updated.
+ * LLM value always has priority — this only fills nulls.
+ *
+ * Usage: npx tsx scripts/backfill-lastcargoes.ts
+ */
+
+import { getDb } from '@/lib/db';
+import { extractLastCargoesFromBody } from '@/lib/parsing/lastcargoes-fallback';
+import type { ParsedVessel } from '@/lib/types';
+
+const db = getDb();
+
+const rows = db
+  .prepare(
+    `SELECT pr.account_id, pr.gmail_message_id, pr.parse_type, pr.parser_version,
+            pr.result_json, e.body
+     FROM parsed_results pr
+     LEFT JOIN emails e
+       ON e.account_id = pr.account_id AND e.gmail_message_id = pr.gmail_message_id
+     WHERE pr.parse_type = 'vessel'`,
+  )
+  .all() as Array<{
+  account_id: string;
+  gmail_message_id: string;
+  parse_type: string;
+  parser_version: string;
+  result_json: string;
+  body: string | null;
+}>;
+
+const update = db.prepare(
+  `UPDATE parsed_results SET result_json = ?
+   WHERE account_id = ? AND gmail_message_id = ? AND parse_type = ? AND parser_version = ?`,
+);
+
+let touched = 0;
+
+const tx = db.transaction(() => {
+  for (const row of rows) {
+    let vessels: ParsedVessel[];
+    try {
+      vessels = JSON.parse(row.result_json) as ParsedVessel[];
+    } catch {
+      continue;
+    }
+
+    let changed = false;
+    for (const v of vessels) {
+      if (v.lastCargoes) continue; // LLM already extracted it
+      if (!row.body) continue;     // no body to scan
+      const fb = extractLastCargoesFromBody(row.body);
+      if (fb) {
+        v.lastCargoes = fb;
+        changed = true;
+      }
+    }
+
+    if (changed) {
+      update.run(
+        JSON.stringify(vessels),
+        row.account_id,
+        row.gmail_message_id,
+        row.parse_type,
+        row.parser_version,
+      );
+      touched++;
+    }
+  }
+});
+
+tx();
+
+console.log(
+  `backfill-lastcargoes: scanned ${rows.length} vessel cache rows, updated ${touched}`,
+);
