+++ b/app/reports/roi/page.tsx
@@ -0,0 +1,115 @@
+import { cookies } from 'next/headers';
+import Link from 'next/link';
+import { redirect } from 'next/navigation';
+import { getSession } from '@/lib/session';
+import { getStore } from '@/lib/session-store';
+import { getRoiSummary } from '@/lib/analytics/roi-metrics';
+import { ChevronLeft, TrendingUp } from 'lucide-react';
+import { Card } from '@/design-system/primitives';
+
+const PLATFORM_COST_USD =
+  Number(process.env.PLATFORM_COST_USD_PER_VOYAGE) || 500;
+
+function fmt(n: number, decimals = 0) {
+  return n.toLocaleString('en-US', {
+    minimumFractionDigits: decimals,
+    maximumFractionDigits: decimals,
+  });
+}
+
+function fmtUsd(n: number) {
+  if (Math.abs(n) >= 1_000_000) return `$${fmt(n / 1_000_000, 2)}M`;
+  if (Math.abs(n) >= 1_000)     return `$${fmt(n / 1_000, 1)}k`;
+  return `$${fmt(n)}`;
+}
+
+export default async function RoiReportPage() {
+  const cookieStore = await cookies();
+  const sessionId = cookieStore.get('session_id')?.value;
+  if (!sessionId || !getSession(sessionId)) redirect('/');
+
+  const db = getStore().getDatabase();
+  const summary = getRoiSummary(db, PLATFORM_COST_USD, 90);
+
+  const isEmpty = summary.totalVoyages === 0;
+
+  return (
+    <main className="min-h-screen bg-ds-bg py-4 sm:py-8 px-3 sm:px-4">
+      <div className="max-w-2xl mx-auto space-y-6">
+        <Link
+          href="/dashboard"
+          className="flex items-center gap-1 text-sm text-ds-text-muted hover:text-ds-text transition-colors"
+        >
+          <ChevronLeft className="h-4 w-4" /> Back to Dashboard
+        </Link>
+
+        <div className="flex items-center gap-2">
+          <TrendingUp className="h-5 w-5 text-ds-accent" />
+          <h1 className="text-lg font-bold text-ds-text">ROI Report — last 90 days</h1>
+        </div>
+
+        {isEmpty ? (
+          <Card padding="md">
+            <p className="text-sm text-ds-text-muted text-center py-4">
+              No voyage data yet. ROI metrics are recorded when fixtures are completed.
+            </p>
+          </Card>
+        ) : (
+          <>
+            {/* Summary KPIs */}
+            <div className="grid grid-cols-2 sm:grid-cols-4 gap-3">
+              {[
+                { label: 'Voyages', value: fmt(summary.totalVoyages) },
+                { label: 'Total savings', value: fmtUsd(summary.totalSavingsUsd) },
+                { label: 'Avg / voyage', value: fmtUsd(summary.avgSavingsPerVoyage) },
+                {
+                  label: 'ROI multiple',
+                  value: summary.roiMultiple > 0 ? `${fmt(summary.roiMultiple, 1)}×` : '—',
+                },
+              ].map(({ label, value }) => (
+                <Card key={label} padding="md">
+                  <p className="text-xs text-ds-text-muted mb-1">{label}</p>
+                  <p className="text-lg font-bold text-ds-text">{value}</p>
+                </Card>
+              ))}
+            </div>
+
+            {/* Monthly cohorts */}
+            {summary.cohorts.length > 0 && (
+              <Card padding="md">
+                <h2 className="text-xs font-semibold text-ds-text-muted uppercase tracking-wide mb-3">
+                  Monthly breakdown
+                </h2>
+                <table className="w-full text-sm">
+                  <thead>
+                    <tr className="text-left text-xs text-ds-text-muted border-b border-ds-border">
+                      <th className="pb-1 pr-4">Month</th>
+                      <th className="pb-1 pr-4 text-right">Voyages</th>
+                      <th className="pb-1 pr-4 text-right">Total savings</th>
+                      <th className="pb-1 text-right">Avg / voyage</th>
+                    </tr>
+                  </thead>
+                  <tbody>
+                    {summary.cohorts.map((c) => (
+                      <tr key={c.month} className="border-b border-ds-border last:border-0">
+                        <td className="py-1.5 pr-4 text-ds-text font-medium">{c.month}</td>
+                        <td className="py-1.5 pr-4 text-right text-ds-text">{fmt(c.voyages)}</td>
+                        <td className="py-1.5 pr-4 text-right text-ds-text">{fmtUsd(c.totalSavings)}</td>
+                        <td className="py-1.5 text-right text-ds-text">{fmtUsd(c.avgSavings)}</td>
+                      </tr>
+                    ))}
+                  </tbody>
+                </table>
+              </Card>
+            )}
+          </>
+        )}
+
+        <p className="text-xs text-ds-text-subtle">
+          Platform cost used for ROI multiple: {fmtUsd(PLATFORM_COST_USD)} / voyage
+          {' '}(set <code>PLATFORM_COST_USD_PER_VOYAGE</code> env var to override).
+        </p>
+      </div>
+    </main>
+  );
+}
